oxy_webhelp_navlinks = {"rsc_encryption_management-d39307e14753":{"topics":[{"title":"Data-at-rest encryption","shortdesc":"<p class=\"shortdesc\">Depending on the specific model of the Rubrik Brik, Rubrik clusters encrypt data at         rest using software or hardware encryption.<\/p>","href":"saas\/rsc_data_at_rest_encryption.html","attributes":{"data-id":"rsc_data_at_rest_encryption"},"menu":{"hasChildren":false},"tocID":"rsc_data_at_rest_encryption-d39307e14767","topics":[]},{"title":"Key management for data-at-rest encryption","shortdesc":"<p class=\"shortdesc\">With advanced key management, including key rotation, rekeying, and KMS integration,         Rubrik enhances data-at-rest encryption by providing secure and flexible management of         encryption keys to ensure ongoing protection of stored data.<\/p>","href":"saas\/key_mgmt_dare.html","attributes":{"data-id":"key_mgmt_dare"},"menu":{"hasChildren":false},"tocID":"key_mgmt_dare-d39307e14778","topics":[]},{"title":"Encryption management details","shortdesc":"<p class=\"shortdesc\">The Encryption Management page provides centralized access to encryption settings,         Key Management Systems, and encryption status, enabling effective management and monitoring         of encryption.<\/p>","href":"saas\/encryption_mgmt_details.html","attributes":{"data-id":"encryption_mgmt_details"},"menu":{"hasChildren":false},"tocID":"encryption_mgmt_details-d39307e14789","next":"encryption_mgmt_details-d39307e14789"},{"title":"Key Management Services","shortdesc":"<p class=\"shortdesc\">Rubrik supports Key Management Services integration so that you can use your own         encryption keys for data at rest. This Bring Your Own Key approach ensures Rubrik never         accesses your master keys.<\/p>","href":"saas\/key_management_service.html","attributes":{"data-id":"key_management_service"},"menu":{"hasChildren":false},"tocID":"key_management_service-d39307e14844","next":"key_management_service-d39307e14844"}]}};